VOLANTE_HUD_BASE64 = """"""


def carregar_imagem_volante_hud():

    try:
        dados = base64.b64decode(VOLANTE_HUD_BASE64)

        imagem = Image.open(
            io.BytesIO(dados)
        ).convert("RGBA")

        imagem.thumbnail(
            (66, 66),
            Image.Resampling.LANCZOS
        )

        return ImageTk.PhotoImage(imagem)

    except:
        return None


# ============================================================
# PROTECAO CONTRA DUAS INSTANCIAS
# ============================================================

def verificar_instancia():

    lock_socket = socket.socket(
        socket.AF_INET,
        socket.SOCK_STREAM
    )

    try:

        lock_socket.bind(
            ("127.0.0.1", LOCK_PORT)
        )

        lock_socket.listen(1)

        return lock_socket

    except OSError:

        sys.exit(0)


instance_lock = verificar_instancia()


# ============================================================
# CONFIG.JSON
# ============================================================

def carregar_config():

    global botao_byte
    global botao_mask
    global range_race
    global range_drift
    global telemetria_habilitada
    global telemetria_posicao

    try:

        if not os.path.exists(CONFIG_FILE):
            return

        with open(
            CONFIG_FILE,
            "r",
            encoding="utf-8"
        ) as arquivo:

            config = json.load(arquivo)

        novo_byte = int(
            config.get(
                "botao_byte",
                BOTAO_BYTE_PADRAO
            )
        )

        nova_mask = int(
            config.get(
                "botao_mask",
                BOTAO_MASK_PADRAO
            )
        )

        # Validacao simples
        if novo_byte < 0:
            return

        if nova_mask <= 0:
            return

        novo_range_race = int(
            config.get(
                "range_race",
                RANGE_RACE_PADRAO
            )
        )

        novo_range_drift = int(
            config.get(
                "range_drift",
                RANGE_DRIFT_PADRAO
            )
        )

        botao_byte = novo_byte
        botao_mask = nova_mask

        if RANGE_MINIMO <= novo_range_race <= RANGE_MAXIMO:
            range_race = novo_range_race

        if RANGE_MINIMO <= novo_range_drift <= RANGE_MAXIMO:
            range_drift = novo_range_drift

        telemetria_habilitada = bool(
            config.get(
                "telemetria_habilitada",
                TELEMETRIA_HABILITADA_PADRAO
            )
        )

        posicao_lida = str(
            config.get(
                "telemetria_posicao",
                TELEMETRIA_POSICAO_PADRAO
            )
        )

        posicoes_validas = {
            "centro_inferior",
            "centro",
            "centro_superior",
            "inferior_esquerda",
            "inferior_direita",
        }

        if posicao_lida in posicoes_validas:
            telemetria_posicao = posicao_lida

    except:
        # Se houver qualquer problema no JSON,
        # usa o botao padrao.
        botao_byte = BOTAO_BYTE_PADRAO
        botao_mask = BOTAO_MASK_PADRAO
        range_race = RANGE_RACE_PADRAO
        range_drift = RANGE_DRIFT_PADRAO
        telemetria_habilitada = TELEMETRIA_HABILITADA_PADRAO
        telemetria_posicao = TELEMETRIA_POSICAO_PADRAO


def salvar_config():

    try:

        config = {
            "botao_byte": botao_byte,
            "botao_mask": botao_mask,
            "range_race": range_race,
            "range_drift": range_drift,
            "telemetria_habilitada": telemetria_habilitada,
            "telemetria_posicao": telemetria_posicao
        }

        with open(
            CONFIG_FILE,
            "w",
            encoding="utf-8"
        ) as arquivo:

            json.dump(
                config,
                arquivo,
                indent=4
            )

        return True

    except:

        return False


# Carrega a configuracao antes de iniciar
carregar_config()


# ============================================================
# LOCALIZAR G29
# ============================================================

def localizar_g29():

    try:

        for d in hid.enumerate(VID, PID):

            if (
                d.get("interface_number") == 0
                and d.get("usage_page") == 1
                and d.get("usage") == 4
            ):

                return d

    except:
        pass

    return None


# ============================================================
# DEFINIR ROTACAO
# ============================================================

def definir_range(graus):

    global device

    if globals().get('map_overlay') and not map_overlay.settings.get('switcher_enabled',True):
        return False

    if device is None:
        return False

    low = graus & 0xFF
    high = (graus >> 8) & 0xFF

    comando = [
        0x00,
        0xF8,
        0x81,
        low,
        high,
        0x00,
        0x00,
        0x00
    ]

    try:

        with device_lock:

            device.write(
                comando
            )

        return True

    except:

        return False


