# ============================================================
# CANTOS ARREDONDADOS DAS JANELAS - WINDOWS 11
# ============================================================

def aplicar_cantos_arredondados(janela):
    """
    Solicita ao DWM do Windows 11 cantos arredondados nativos.
    Funciona sem desenhar uma borda artificial e preserva alpha/fades.
    """
    if sys.platform != "win32":
        return

    try:
        # Garante que o HWND real da janela já tenha sido criado.
        janela.update_idletasks()

        hwnd_tk = janela.winfo_id()

        # Em Tkinter, o HWND retornado pode ser uma janela filha.
        # O parent normalmente é o HWND real do Toplevel.
        hwnd = ctypes.windll.user32.GetParent(hwnd_tk)
        if not hwnd:
            hwnd = hwnd_tk

        # Windows 11:
        # DWMWA_WINDOW_CORNER_PREFERENCE = 33
        # DWMWCP_ROUND = 2
        preferencia = ctypes.c_int(2)

        ctypes.windll.dwmapi.DwmSetWindowAttribute(
            hwnd,
            33,
            ctypes.byref(preferencia),
            ctypes.sizeof(preferencia)
        )

    except Exception:
        # Em versões antigas do Windows, simplesmente mantém
        # o comportamento original.
        pass


def aplicar_regiao_arredondada(janela, largura, altura, raio=10):
    """
    Recorta fisicamente a janela em um retângulo arredondado.
    É usado no indicador permanente porque o DWM pode ignorar
    os cantos nativos em Toplevel sem moldura/transparentcolor.
    """
    if sys.platform != "win32":
        return

    try:
        janela.update_idletasks()

        hwnd_tk = janela.winfo_id()
        hwnd = ctypes.windll.user32.GetParent(hwnd_tk)
        if not hwnd:
            hwnd = hwnd_tk

        diametro = max(2, raio * 2)
        regiao = ctypes.windll.gdi32.CreateRoundRectRgn(
            0,
            0,
            largura + 1,
            altura + 1,
            diametro,
            diametro
        )

        if regiao:
            # O Windows passa a ser o dono da região após SetWindowRgn.
            ctypes.windll.user32.SetWindowRgn(hwnd, regiao, True)

    except Exception:
        pass


# ============================================================
# CRIAR HUD
