def fade_creditos_in(alpha):

    global creditos_job

    if creditos is None:
        return

    if alpha >= 0.96:

        creditos.attributes(
            "-alpha",
            0.96
        )

        # Mantem a tela visivel e inicia o fade-out.
        # O ciclo completo dura aproximadamente 5 segundos.
        creditos_job = root.after(
            4000,
            lambda: fade_creditos_out(0.96)
        )

        return

    creditos.attributes(
        "-alpha",
        alpha
    )

    creditos_job = root.after(
        20,
        lambda: fade_creditos_in(
            alpha + 0.08
        )
    )


def fade_creditos_out(alpha):

    global creditos
    global creditos_job

    if creditos is None:
        return

    if alpha <= 0:

        try:
            creditos.destroy()
        except:
            pass

        creditos = None
        creditos_job = None
        return

    creditos.attributes(
        "-alpha",
        max(0, alpha)
    )

    creditos_job = root.after(
        20,
        lambda: fade_creditos_out(
            alpha - 0.08
        )
    )


# ============================================================
# OVERLAY ANTIALIAS DO INDICADOR - WINDOWS
# ============================================================

class _POINT(ctypes.Structure):
    _fields_ = [
        ("x", ctypes.c_long),
        ("y", ctypes.c_long),
    ]


class _SIZE(ctypes.Structure):
    _fields_ = [
        ("cx", ctypes.c_long),
        ("cy", ctypes.c_long),
    ]


class _BLENDFUNCTION(ctypes.Structure):
    _fields_ = [
        ("BlendOp", ctypes.c_ubyte),
        ("BlendFlags", ctypes.c_ubyte),
        ("SourceConstantAlpha", ctypes.c_ubyte),
        ("AlphaFormat", ctypes.c_ubyte),
    ]


class _BITMAPINFOHEADER(ctypes.Structure):
    _fields_ = [
        ("biSize", ctypes.c_uint32),
        ("biWidth", ctypes.c_long),
        ("biHeight", ctypes.c_long),
        ("biPlanes", ctypes.c_ushort),
        ("biBitCount", ctypes.c_ushort),
        ("biCompression", ctypes.c_uint32),
        ("biSizeImage", ctypes.c_uint32),
        ("biXPelsPerMeter", ctypes.c_long),
        ("biYPelsPerMeter", ctypes.c_long),
        ("biClrUsed", ctypes.c_uint32),
        ("biClrImportant", ctypes.c_uint32),
    ]


class _BITMAPINFO(ctypes.Structure):
    _fields_ = [
        ("bmiHeader", _BITMAPINFOHEADER),
        ("bmiColors", ctypes.c_uint32 * 3),
    ]


def configurar_api_overlay_win32():
    """
    Configura assinaturas Win32/GDI para Python 64-bit.
    Sem isto, alguns handles podem ser tratados como int de 32 bits
    e o overlay transparente simplesmente não aparece.
    """
    if sys.platform != "win32":
        return

    user32 = ctypes.windll.user32
    gdi32 = ctypes.windll.gdi32
    kernel32 = ctypes.windll.kernel32

    HANDLE = ctypes.c_void_p
    HWND = ctypes.c_void_p
    HDC = ctypes.c_void_p
    HGDIOBJ = ctypes.c_void_p
    HBITMAP = ctypes.c_void_p
    HINSTANCE = ctypes.c_void_p
    HMENU = ctypes.c_void_p

    user32.CreateWindowExW.argtypes = [
        ctypes.c_uint32,
        ctypes.c_wchar_p,
        ctypes.c_wchar_p,
        ctypes.c_uint32,
        ctypes.c_int,
        ctypes.c_int,
        ctypes.c_int,
        ctypes.c_int,
        HWND,
        HMENU,
        HINSTANCE,
        ctypes.c_void_p,
    ]
    user32.CreateWindowExW.restype = HWND

    kernel32.GetModuleHandleW.argtypes = [
        ctypes.c_wchar_p
    ]
    kernel32.GetModuleHandleW.restype = HINSTANCE

    user32.GetDC.argtypes = [HWND]
    user32.GetDC.restype = HDC

    user32.ReleaseDC.argtypes = [
        HWND,
        HDC,
    ]
    user32.ReleaseDC.restype = ctypes.c_int

    gdi32.CreateCompatibleDC.argtypes = [
        HDC
    ]
    gdi32.CreateCompatibleDC.restype = HDC

    gdi32.DeleteDC.argtypes = [
        HDC
    ]
    gdi32.DeleteDC.restype = ctypes.c_int

    gdi32.CreateDIBSection.argtypes = [
        HDC,
        ctypes.POINTER(_BITMAPINFO),
        ctypes.c_uint,
        ctypes.POINTER(ctypes.c_void_p),
        HANDLE,
        ctypes.c_uint32,
    ]
    gdi32.CreateDIBSection.restype = HBITMAP

    gdi32.SelectObject.argtypes = [
        HDC,
        HGDIOBJ,
    ]
    gdi32.SelectObject.restype = HGDIOBJ

    gdi32.DeleteObject.argtypes = [
        HGDIOBJ
    ]
    gdi32.DeleteObject.restype = ctypes.c_int

    user32.UpdateLayeredWindow.argtypes = [
        HWND,
        HDC,
        ctypes.POINTER(_POINT),
        ctypes.POINTER(_SIZE),
        HDC,
        ctypes.POINTER(_POINT),
        ctypes.c_uint32,
        ctypes.POINTER(_BLENDFUNCTION),
        ctypes.c_uint32,
    ]
    user32.UpdateLayeredWindow.restype = ctypes.c_int

    user32.SetWindowPos.argtypes = [
        HWND,
        HWND,
        ctypes.c_int,
        ctypes.c_int,
        ctypes.c_int,
        ctypes.c_int,
        ctypes.c_uint,
    ]
    user32.SetWindowPos.restype = ctypes.c_int

    user32.ShowWindow.argtypes = [
        HWND,
        ctypes.c_int,
    ]
    user32.ShowWindow.restype = ctypes.c_int

    user32.DestroyWindow.argtypes = [
        HWND
    ]
    user32.DestroyWindow.restype = ctypes.c_int


def criar_janela_overlay_nativa():
    """
    Cria uma janela Win32 nativa APENAS para RACE/DRIFT.

    Ela fica acima do painel, não tem fundo e não recebe o alpha/fade
    aplicado ao indicador_fundo.
    """
    if sys.platform != "win32":
        return None

    try:
        configurar_api_overlay_win32()

        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32

        WS_POPUP = 0x80000000

        WS_EX_TOPMOST = 0x00000008
        WS_EX_TRANSPARENT = 0x00000020
        WS_EX_TOOLWINDOW = 0x00000080
        WS_EX_LAYERED = 0x00080000
        WS_EX_NOACTIVATE = 0x08000000

        ex_style = (
            WS_EX_TOPMOST
            | WS_EX_TRANSPARENT
            | WS_EX_TOOLWINDOW
            | WS_EX_LAYERED
            | WS_EX_NOACTIVATE
        )

        # A camada do texto é pequena para não existir uma grande
        # superfície invisível sobre a tela.
        largura_texto = 120
        altura_texto = 28

        largura_tela = root.winfo_screenwidth()

        x_painel = (
            largura_tela - INDICADOR_LARGURA
        ) // 2

        x = (
            x_painel
            + (INDICADOR_LARGURA - largura_texto) // 2
        )

        y = INDICADOR_MARGEM_SUPERIOR + 6

        hwnd = user32.CreateWindowExW(
            ex_style,
            "STATIC",
            "",
            WS_POPUP,
            x,
            y,
            largura_texto,
            altura_texto,
            None,
            None,
            kernel32.GetModuleHandleW(None),
            None
        )

        if not hwnd:
            return None

        return hwnd

    except Exception:
        return None

def ocultar_overlay_indicador():
    if (
        sys.platform != "win32"
        or indicador is None
    ):
        return

    try:
        SW_HIDE = 0
        ctypes.windll.user32.ShowWindow(
            indicador,
            SW_HIDE
        )
    except Exception:
        pass


def destruir_overlay_indicador():
    global indicador

    if (
        sys.platform == "win32"
        and indicador is not None
    ):
        try:
            ctypes.windll.user32.DestroyWindow(
                indicador
            )
        except Exception:
            pass

    indicador = None


def criar_bitmap_overlay_modo(texto, cor):
    """
    Desenha SOMENTE RACE/DRIFT em RGBA real.

    O texto é renderizado separado do fundo, portanto o fade do painel
    não altera a nitidez nem a opacidade das letras.
    """
    largura = 120
    altura = 28

    # Supersampling 4x para suavizar bem as bordas.
    escala = 4

    imagem_hi = Image.new(
        "RGBA",
        (
            largura * escala,
            altura * escala
        ),
        (0, 0, 0, 0)
    )

    draw = ImageDraw.Draw(imagem_hi)

    cor_rgb = tuple(
        int(cor[i:i + 2], 16)
        for i in (1, 3, 5)
    )

    fonte = None

    for caminho in (
        r"C:\Windows\Fonts\segoeuib.ttf",
        r"C:\Windows\Fonts\arialbd.ttf",
    ):
        try:
            fonte = ImageFont.truetype(
                caminho,
                16 * escala
            )
            break
        except Exception:
            pass

    if fonte is None:
        fonte = ImageFont.load_default()

    bbox = draw.textbbox(
        (0, 0),
        texto,
        font=fonte
    )

    texto_largura = bbox[2] - bbox[0]
    texto_altura = bbox[3] - bbox[1]

    x = (
        ((largura * escala) - texto_largura) / 2
        - bbox[0]
    )

    y = (
        ((altura * escala) - texto_altura) / 2
        - bbox[1]
    )

    draw.text(
        (x, y),
        texto,
        font=fonte,
        fill=(*cor_rgb, 255)
    )

    return imagem_hi.resize(
        (largura, altura),
        Image.Resampling.LANCZOS
    )

def atualizar_overlay_indicador(texto, cor):
    """
    Atualiza a janela Win32 usando alpha por pixel.

    O texto fica 100% opaco no centro e suavizado nas bordas,
    enquanto todo o restante da janela continua invisível.
    """
    if (
        sys.platform != "win32"
        or indicador is None
    ):
        return

    configurar_api_overlay_win32()

    user32 = ctypes.windll.user32
    gdi32 = ctypes.windll.gdi32

    hdc_tela = None
    hdc_memoria = None
    hbitmap = None
    antigo = None

    try:
        imagem = criar_bitmap_overlay_modo(
            texto,
            cor
        )

        largura, altura = imagem.size

        # UpdateLayeredWindow precisa dos canais em BGRA premultiplicados.
        rgba = imagem.tobytes()
        pixels = bytearray(
            largura * altura * 4
        )

        for i in range(
            largura * altura
        ):
            p = i * 4

            r = rgba[p]
            g = rgba[p + 1]
            b = rgba[p + 2]
            a = rgba[p + 3]

            pixels[p] = (
                b * a + 127
            ) // 255

            pixels[p + 1] = (
                g * a + 127
            ) // 255

            pixels[p + 2] = (
                r * a + 127
            ) // 255

            pixels[p + 3] = a

        hdc_tela = user32.GetDC(None)

        hdc_memoria = (
            gdi32.CreateCompatibleDC(
                hdc_tela
            )
        )

        bmi = _BITMAPINFO()

        bmi.bmiHeader.biSize = (
            ctypes.sizeof(
                _BITMAPINFOHEADER
            )
        )

        bmi.bmiHeader.biWidth = largura

        # Valor negativo = bitmap top-down.
        bmi.bmiHeader.biHeight = -altura

        bmi.bmiHeader.biPlanes = 1
        bmi.bmiHeader.biBitCount = 32
        bmi.bmiHeader.biCompression = 0

        bits = ctypes.c_void_p()

        hbitmap = gdi32.CreateDIBSection(
            hdc_tela,
            ctypes.byref(bmi),
            0,
            ctypes.byref(bits),
            None,
            0
        )

        if not hbitmap or not bits:
            return

        antigo = gdi32.SelectObject(
            hdc_memoria,
            hbitmap
        )

        buffer = (
            ctypes.c_ubyte
            * len(pixels)
        ).from_buffer(pixels)

        ctypes.memmove(
            bits,
            buffer,
            len(pixels)
        )

        largura_tela = root.winfo_screenwidth()

        x_painel = (
            largura_tela - INDICADOR_LARGURA
        ) // 2

        destino = _POINT(
            (
                x_painel
                + (INDICADOR_LARGURA - largura) // 2
            ),
            INDICADOR_MARGEM_SUPERIOR + 6
        )

        origem = _POINT(0, 0)

        tamanho = _SIZE(
            largura,
            altura
        )

        blend = _BLENDFUNCTION(
            0,      # AC_SRC_OVER
            0,
            255,
            1       # AC_SRC_ALPHA
        )

        ULW_ALPHA = 0x00000002

        ok = user32.UpdateLayeredWindow(
            indicador,
            hdc_tela,
            ctypes.byref(destino),
            ctypes.byref(tamanho),
            hdc_memoria,
            ctypes.byref(origem),
            0,
            ctypes.byref(blend),
            ULW_ALPHA
        )

        if not ok:
            return

        # Mantém sobre o fundo sem roubar o foco.
        HWND_TOPMOST = ctypes.c_void_p(-1)

        SWP_NOSIZE = 0x0001
        SWP_NOMOVE = 0x0002
        SWP_NOACTIVATE = 0x0010
        SWP_SHOWWINDOW = 0x0040

        user32.SetWindowPos(
            indicador,
            HWND_TOPMOST,
            0,
            0,
            0,
            0,
            (
                SWP_NOSIZE
                | SWP_NOMOVE
                | SWP_NOACTIVATE
                | SWP_SHOWWINDOW
            )
        )

        # SW_SHOWNOACTIVATE = 4
        user32.ShowWindow(
            indicador,
            4
        )

    except Exception:
        pass

    finally:
        try:
            if (
                hdc_memoria
                and antigo
            ):
                gdi32.SelectObject(
                    hdc_memoria,
                    antigo
                )
        except Exception:
            pass

        try:
            if hbitmap:
                gdi32.DeleteObject(
                    hbitmap
                )
        except Exception:
            pass

        try:
            if hdc_memoria:
                gdi32.DeleteDC(
                    hdc_memoria
                )
        except Exception:
            pass

        try:
            if hdc_tela:
                user32.ReleaseDC(
                    None,
                    hdc_tela
                )
        except Exception:
            pass


# ============================================================
# INDICADOR PERMANENTE DO MODO
# ============================================================

def criar_indicador_modo():
    global indicador
    global indicador_fundo
    global indicador_barra
    global indicador_canvas_fundo
    global indicador_g29
    global indicador_modo

    largura_tela = root.winfo_screenwidth()

    x = (
        largura_tela - INDICADOR_LARGURA
    ) // 2

    y = INDICADOR_MARGEM_SUPERIOR

    geometria = (
        f"{INDICADOR_LARGURA}x{INDICADOR_ALTURA}"
        f"+{x}+{y}"
    )

    # --------------------------------------------------------
    # CAMADA 1: FUNDO
    # Continua exatamente como antes e mantém o fade.
    # --------------------------------------------------------
    indicador_fundo = tk.Toplevel(root)

    indicador_fundo.withdraw()
    indicador_fundo.overrideredirect(True)

    indicador_fundo.configure(
        bg="#080A0D"
    )

    indicador_fundo.geometry(geometria)

    try:
        indicador_fundo.attributes(
            "-topmost",
            True
        )

        indicador_fundo.attributes(
            "-toolwindow",
            True
        )

        indicador_fundo.attributes(
            "-alpha",
            INDICADOR_ALPHA_FUNDO_ATIVO
        )

    except Exception:
        pass

    aplicar_cantos_arredondados(
        indicador_fundo
    )

    indicador_canvas_fundo = tk.Canvas(
        indicador_fundo,
        width=INDICADOR_LARGURA,
        height=INDICADOR_ALTURA,
        bg="#080A0D",
        highlightthickness=0,
        bd=0
    )

    indicador_canvas_fundo.pack(
        fill="both",
        expand=True
    )

    indicador_canvas_fundo.create_rectangle(
        1,
        1,
        INDICADOR_LARGURA - 2,
        INDICADOR_ALTURA - 2,
        outline="#20262D",
        width=1
    )

    # Barra superior pertence ao painel/fundo.
    # O texto fica em uma camada independente por cima.
    indicador_barra = indicador_canvas_fundo.create_rectangle(
        26,
        0,
        184,
        4,
        fill="#4DA3FF",
        outline=""
    )

    # --------------------------------------------------------
    # CAMADA 2: BARRA + TEXTO
    # Agora é uma janela Win32 nativa e não um Toplevel do Tk.
    # --------------------------------------------------------
    indicador = criar_janela_overlay_nativa()

    indicador_g29 = None
    indicador_modo = None


def cancelar_fade_indicador():
    global indicador_fade_job

    if indicador_fade_job is not None and root is not None:
        try:
            root.after_cancel(indicador_fade_job)
        except Exception:
            pass

    indicador_fade_job = None


def iniciar_fade_indicador():
    global indicador_fade_job

    cancelar_fade_indicador()

    if indicador_fundo is None or root is None:
        return

    # Toda troca de modo restaura imediatamente o fundo.
    try:
        indicador_fundo.attributes(
            "-alpha",
            INDICADOR_ALPHA_FUNDO_ATIVO
        )
    except Exception:
        pass

    indicador_fade_job = root.after(
        INDICADOR_FADE_ESPERA,
        lambda: fade_background_indicador(0.0)
    )


def fade_background_indicador(progresso=0.0):
    global indicador_fade_job

    if (
        indicador_fundo is None
        or root is None
        or not g29_conectado
    ):
        indicador_fade_job = None
        return

    progresso = max(0.0, min(1.0, progresso))

    alpha = (
        INDICADOR_ALPHA_FUNDO_ATIVO
        + (
            INDICADOR_ALPHA_FUNDO_REPOUSO
            - INDICADOR_ALPHA_FUNDO_ATIVO
        ) * progresso
    )

    try:
        indicador_fundo.attributes("-alpha", alpha)
    except Exception:
        pass

    if progresso >= 1.0:
        indicador_fade_job = None
        return

    passos = max(
        1,
        int(INDICADOR_FADE_DURACAO / 20)
    )

    indicador_fade_job = root.after(
        20,
        lambda: fade_background_indicador(
            progresso + (1.0 / passos)
        )
    )


def atualizar_indicador_modo():
    if root is not None:
        root.after(0, aplicar_indicador_modo)


def aplicar_indicador_modo():
    if globals().get('map_overlay') and (not map_overlay.settings.get('show_mode_indicator',True) or not map_overlay.settings.get('switcher_enabled',True)):
        cancelar_fade_indicador()
        ocultar_overlay_indicador()
        if indicador_fundo is not None: indicador_fundo.withdraw()
        return
    if indicador_fundo is None:
        return

    if not g29_conectado:
        cancelar_fade_indicador()

        ocultar_overlay_indicador()

        indicador_fundo.withdraw()

        return

    if modo_drift:
        cor = "#FF8C42"
        texto = "DRIFT"
    else:
        cor = "#4DA3FF"
        texto = "RACE"

    # Atualiza a cor da barra que faz parte do painel.
    if (
        indicador_canvas_fundo is not None
        and indicador_barra is not None
    ):
        try:
            indicador_canvas_fundo.itemconfigure(
                indicador_barra,
                fill=cor
            )
        except Exception:
            pass

    # Fundo arredondado.
    indicador_fundo.attributes(
        "-alpha",
        INDICADOR_ALPHA_FUNDO_ATIVO
    )

    indicador_fundo.deiconify()
    indicador_fundo.lift()

    # TEXTO em camada independente por cima do painel.
    # Esta janela não recebe nenhum alpha do fade.
    if indicador is not None:
        atualizar_overlay_indicador(
            texto,
            cor
        )

    # Reinicia o fade apenas do fundo.
    iniciar_fade_indicador()


# ============================================================
# MOSTRAR HUD
# ============================================================

def mostrar_hud(
    modo,
    texto_direita="",
    cor="#4DA3FF",
    tempo=None
):

    if root is None:
        return

    root.after(
        0,
        lambda: iniciar_hud(
            modo,
            texto_direita,
            cor,
            tempo
        )
    )


def iniciar_hud(
    modo,
    texto_direita,
    cor,
    tempo
):

    global hud_job

    if hud is None:
        return

    # Posiciona a notificacao de troca de modo logo abaixo
    # do indicador permanente no topo/centro da tela.
    if modo in ("RACE MODE", "DRIFT MODE"):

        largura_tela = hud.winfo_screenwidth()

        x_hud = (
            largura_tela
            - HUD_LARGURA
        ) // 2

        y_hud = (
            INDICADOR_MARGEM_SUPERIOR
            + INDICADOR_ALTURA
            + 6
        )

    else:

        # Outros avisos continuam no canto superior direito.
        largura_tela = hud.winfo_screenwidth()

        x_hud = (
            largura_tela
            - HUD_LARGURA
            - HUD_MARGEM_DIREITA
        )

        y_hud = HUD_MARGEM_SUPERIOR

    hud.geometry(
        f"{HUD_LARGURA}x{HUD_ALTURA}+{x_hud}+{y_hud}"
    )

    # Cancela a animacao anterior
    if hud_job is not None:

        try:
            root.after_cancel(
                hud_job
            )
        except:
            pass

        hud_job = None

    # Mantem apenas RACE/DRIFT no texto principal,
    # mesmo quando outras mensagens usam o mesmo HUD.
    texto_modo = modo

    if modo == "RACE MODE":
        texto_modo = "RACE"

    elif modo == "DRIFT MODE":
        texto_modo = "DRIFT"

    # Ajusta automaticamente o tamanho da fonte para mensagens longas
    # (ex.: PRESSSIONE O BOTAO / BOTAO CONFIGURADO), mantendo RACE/DRIFT maiores.
    tamanho_fonte = 13
    if len(texto_modo) > 17:
        tamanho_fonte = 9
    elif len(texto_modo) > 12:
        tamanho_fonte = 10
    elif len(texto_modo) > 8:
        tamanho_fonte = 11

    hud_canvas.itemconfig(
        hud_modo,
        text=texto_modo,
        fill=cor,
        font=("Segoe UI", tamanho_fonte, "bold")
    )

    hud_canvas.itemconfig(
        hud_graus,
        text=texto_direita
    )

    atualizar_barra_segmentada(
        cor,
        texto_direita
    )

    hud.attributes(
        "-alpha",
        0.0
    )

    hud.deiconify()
    hud.lift()

    fade_in(
        0.0,
        tempo
    )


# ============================================================
# FADE IN
# ============================================================

def fade_in(
    alpha,
    tempo=None
):

    global hud_job

    if alpha >= 0.96:

        hud.attributes(
            "-alpha",
            0.96
        )

        if tempo is None:
            tempo = HUD_TEMPO_VISIVEL

        hud_job = root.after(
            tempo,
            lambda: fade_out(0.96)
        )

        return

    hud.attributes(
        "-alpha",
        alpha
    )

    passos = max(
        1,
        int(HUD_FADE_IN / 20)
    )

    incremento = (
        0.96 / passos
    )

    hud_job = root.after(
        20,
        lambda: fade_in(
            alpha + incremento,
            tempo
        )
    )


# ============================================================
# FADE OUT
# ============================================================

def fade_out(alpha):

    global hud_job

    if alpha <= 0:

        hud.attributes(
            "-alpha",
            0.0
        )

        hud.withdraw()

        hud_job = None

        return

    passos = max(
        1,
        int(HUD_FADE_OUT / 20)
    )

    decremento = (
        0.96 / passos
    )

    hud.attributes(
        "-alpha",
        max(0, alpha)
    )

    hud_job = root.after(
        20,
        lambda: fade_out(
            alpha - decremento
        )
    )


