def detectar_bit_alterado(estado_base, estado_atual):
    before=pressed(estado_base,g29_button_layout)
    after=pressed(estado_atual,g29_button_layout)
    if before is None or after is None or before or len(after)!=1:return None
    return next(iter(after))


# ============================================================
# CONFIGURAR NOVO BOTAO
# ============================================================

def configurar_botao(
    icon=None,
    item=None
):

    global configurando_botao

    if not g29_conectado:

        mostrar_hud(
            "G29 DISCONNECTED",
            "!",
            "#FF4D4D",
            1300
        )

        return

    if configurando_botao:
        return

    configurando_botao = True

    atualizar_tray()

    mostrar_hud(
        "PRESS AND RELEASE ONE BUTTON",
        "10s",
        "#FFD54A",
        1500
    )

    thread = threading.Thread(
        target=aprender_botao,
        daemon=True
    )

    thread.start()


# ============================================================
# APRENDER BOTAO
# ============================================================

def aprender_botao():
    global configurando_botao, botao_byte, botao_mask
    original=(botao_byte,botao_mask)
    capture=ButtonCapture()
    with device_lock:
        target=device
        layout=g29_button_layout
        initial=g29_last_report
    if initial:capture.feed(initial,layout,time.monotonic())
    try:
        if not layout:
            mostrar_hud('BUTTON DATA UNAVAILABLE','!', '#FF4D4D',1800)
            return
        started=time.monotonic()
        while configurando_botao and not encerrar_programa and time.monotonic()-started<TEMPO_CONFIGURACAO_BOTAO:
            with device_lock:
                if device is not target or target is None:return
                data=target.read(64)
            result=capture.feed(data,layout,time.monotonic()) if data else None
            if result is not None:
                botao_byte,botao_mask=result
                if salvar_config():
                    mostrar_hud('BUTTON CONFIGURED','OK','#44D17A',1300)
                else:
                    botao_byte,botao_mask=original
                    mostrar_hud('SAVE FAILED','!','#FF4D4D',1300)
                return
            time.sleep(.005)
        if not encerrar_programa:mostrar_hud('TIMED OUT','X','#FF4D4D',1200)
    except (OSError,ValueError):
        mostrar_hud('UNABLE TO READ','!','#FF4D4D',1200)
    finally:
        configurando_botao=False
        atualizar_tray()


