def abrir_configuracao_rotacao(modo):

    if root is None:
        return

    root.after(
        0,
        lambda: criar_janela_rotacao(modo)
    )


def configurar_rotacao_race(
    icon=None,
    item=None
):

    abrir_configuracao_rotacao("RACE")


def configurar_rotacao_drift(
    icon=None,
    item=None
):

    abrir_configuracao_rotacao("DRIFT")


def criar_janela_rotacao(modo):

    global range_race
    global range_drift

    janela = tk.Toplevel(root)

    janela.title(
        f"Configure {modo}"
    )

    janela.resizable(
        False,
        False
    )

    janela.attributes(
        "-topmost",
        True
    )

    janela.configure(
        bg="#111318"
    )

    largura = 330
    altura = 175

    x = (
        janela.winfo_screenwidth()
        - largura
    ) // 2

    y = (
        janela.winfo_screenheight()
        - altura
    ) // 2

    janela.geometry(
        f"{largura}x{altura}+{x}+{y}"
    )

    aplicar_cantos_arredondados(janela)

    valor_atual = (
        range_race
        if modo == "RACE"
        else range_drift
    )

    titulo = tk.Label(
        janela,
        text=f"{modo} rotation",
        font=("Segoe UI", 11, "bold"),
        fg="white",
        bg="#111318"
    )

    titulo.pack(
        pady=(18, 8)
    )

    frame_valor = tk.Frame(
        janela,
        bg="#111318"
    )

    frame_valor.pack()

    entrada = tk.Entry(
        frame_valor,
        width=7,
        justify="center",
        font=("Segoe UI", 16, "bold")
    )

    entrada.insert(
        0,
        str(valor_atual)
    )

    entrada.pack(
        side="left"
    )

    graus_label = tk.Label(
        frame_valor,
        text="°",
        font=("Segoe UI", 16, "bold"),
        fg="white",
        bg="#111318"
    )

    graus_label.pack(
        side="left",
        padx=(4, 0)
    )

    info = tk.Label(
        janela,
        text=f"Allowed range: {RANGE_MINIMO}° to {RANGE_MAXIMO}°",
        font=("Segoe UI", 8),
        fg="#8B949E",
        bg="#111318"
    )

    info.pack(
        pady=(6, 10)
    )

    frame_botoes = tk.Frame(
        janela,
        bg="#111318"
    )

    frame_botoes.pack()

    def salvar():

        global range_race
        global range_drift

        try:

            novo_valor = int(
                entrada.get().strip()
            )

        except ValueError:

            mostrar_hud(
                "INVALID VALUE",
                "!",
                "#FF4D4D",
                1300
            )

            return

        if not (
            RANGE_MINIMO
            <= novo_valor
            <= RANGE_MAXIMO
        ):

            mostrar_hud(
                "INVALID VALUE",
                f"{RANGE_MINIMO}-{RANGE_MAXIMO}°",
                "#FF4D4D",
                1500
            )

            return

        if modo == "RACE":
            range_race = novo_valor
        else:
            range_drift = novo_valor

        if not salvar_config():

            mostrar_hud(
                "SAVE FAILED",
                "!",
                "#FF4D4D",
                1300
            )

            return

        # Se o modo alterado estiver ativo, aplica imediatamente.
        if g29_conectado:

            if (
                modo == "RACE"
                and not modo_drift
            ):
                definir_range(
                    range_race
                )

            elif (
                modo == "DRIFT"
                and modo_drift
            ):
                definir_range(
                    range_drift
                )

        janela.destroy()

        mostrar_hud(
            f"{modo} CONFIGURED",
            f"{novo_valor}°",
            "#4DA3FF"
            if modo == "RACE"
            else "#FF8C42",
            1300
        )

        atualizar_tray()

    botao_cancelar = tk.Button(
        frame_botoes,
        text="Cancel",
        width=10,
        command=janela.destroy
    )

    botao_cancelar.pack(
        side="left",
        padx=5
    )

    botao_salvar = tk.Button(
        frame_botoes,
        text="Save",
        width=10,
        command=salvar
    )

    botao_salvar.pack(
        side="left",
        padx=5
    )

    janela.bind(
        "<Return>",
        lambda event: salvar()
    )

    janela.bind(
        "<Escape>",
        lambda event: janela.destroy()
    )

    entrada.focus_set()
    entrada.selection_range(
        0,
        tk.END
    )


