def texto_menu_drift(item):

    return f"DRIFT - {range_drift}°"


def race_marcado(item):

    return (
        g29_conectado
        and not modo_drift
        and not configurando_botao
    )


def drift_marcado(item):

    return (
        g29_conectado
        and modo_drift
        and not configurando_botao
    )


# ============================================================
# LOOP DO G29
# ============================================================

def loop_g29():
    global g29_button_layout, g29_last_report

    global device
    global g29_conectado
    global modo_drift
    global forcar_reconexao
    global configurando_botao

    while not encerrar_programa:

        try:

            # ------------------------------------------------
            # PROCURAR G29
            # ------------------------------------------------

            g29 = localizar_g29()

            if g29 is None:

                g29_conectado = False

                atualizar_tray()

                time.sleep(
                    TEMPO_RECONEXAO
                )

                continue

            # ------------------------------------------------
            # CONECTAR
            # ------------------------------------------------

            novo_device = hid.device()

            novo_device.open_path(
                g29["path"]
            )

            novo_device.set_nonblocking(
                True
            )

            try:
                layout=button_layout(novo_device.get_report_descriptor())
            except (OSError,ValueError,AttributeError):
                layout={}
            with device_lock:

                g29_button_layout=layout
                g29_last_report=None
                device = novo_device

            g29_conectado = True
            forcar_reconexao = False
            configurando_botao = False

            # Sempre inicia/reconecta em Race
            modo_drift = False

            definir_range(
                range_race
            )

            mostrar_hud(
                "RACE MODE",
                f"{range_race}°",
                "#4DA3FF"
            )

            atualizar_tray()

            estado_anterior = False

            # ------------------------------------------------
            # LEITURA DO G29
            # ------------------------------------------------

            while (
                not encerrar_programa
                and not forcar_reconexao
            ):

                # Durante configuracao do botao,
                # a thread de aprendizado faz
                # a leitura HID.
                if configurando_botao:

                    time.sleep(0.01)
                    continue

                try:

                    with device_lock:

                        if configurando_botao:continue
                        dados = device.read(
                            64
                        )
                        if dados:g29_last_report=bytes(dados)

                except:

                    break

                if dados and not configurando_botao:

                    pressionado = (
                        botao_pressionado(
                            dados
                        )
                    )

                    if (
                        pressionado
                        and not estado_anterior
                    ):

                        alternar_modo()

                    estado_anterior = (
                        pressionado
                    )

                time.sleep(0.005)

        except:

            pass

        # ----------------------------------------------------
        # DESCONECTADO
        # ----------------------------------------------------

        configurando_botao = False
        g29_conectado = False

        atualizar_tray()

        with device_lock:

            if device is not None:

                try:

                    device.close()

                except:

                    pass

                device = None

        forcar_reconexao = False

        if not encerrar_programa:

            time.sleep(
                TEMPO_RECONEXAO
            )


# ============================================================
# ICONE DA BANDEJA
# ============================================================

def caminho_recurso(nome_arquivo):

    # Quando estiver rodando como EXE do PyInstaller
    if getattr(sys, "frozen", False):

        pasta = sys._MEIPASS

    # Quando estiver rodando diretamente pelo Python
    else:

        pasta = os.path.dirname(
            os.path.abspath(__file__)
        )

    return os.path.join(
        pasta,
        nome_arquivo
    )


def criar_imagem_icone():

    try:

        caminho_icone = caminho_recurso(
            "g29_tray.ico"
        )

        imagem = Image.open(
            caminho_icone
        )

        imagem = imagem.convert(
            "RGBA"
        )

        return imagem

    except:

        # Icone de emergencia caso o arquivo
        # nao possa ser carregado.

        tamanho = 64

        imagem = Image.new(
            "RGB",
            (tamanho, tamanho),
            "black"
        )

        draw = ImageDraw.Draw(
            imagem
        )

        draw.ellipse(
            (5, 5, 59, 59),
            outline="white",
            width=5
        )

        draw.ellipse(
            (25, 25, 39, 39),
            fill="white"
        )

        return imagem


